class Solution {
    void parse(const string& s, int& outReal, int& outImag) {
        int i = 0, sign = 1, v = 0;
        if (s[i] == '-') { sign = -1; i++; }
        while (i < (int)s.size() && s[i] >= '0' && s[i] <= '9') {
            v = v * 10 + (s[i] - '0');
            i++;
        }
        outReal = sign * v;
        i++; // skip '+'
        sign = 1; v = 0;
        if (i < (int)s.size() && s[i] == '-') { sign = -1; i++; }
        while (i < (int)s.size() && s[i] >= '0' && s[i] <= '9') {
            v = v * 10 + (s[i] - '0');
            i++;
        }
        outImag = sign * v;
    }
public:
    string complexNumberMultiply(string num1, string num2) {
        int a, b, c, d;
        parse(num1, a, b);
        parse(num2, c, d);
        int real = a * c - b * d;
        int imag = a * d + b * c;
        return to_string(real) + "+" + to_string(imag) + "i";
    }
};
